script:
frappe.call({method: "stockist_dashboard_stats"}).then(r => {
	const d = r.message || {};
	const fmt = n => "₹" + Math.round(n).toLocaleString("en-IN");
	root_element.getElementById("sk-new-orders").textContent = d.new_orders ?? "--";
	root_element.getElementById("sk-today-sales").textContent = fmt(d.today_sales || 0);
	root_element.getElementById("sk-total-dues").textContent = fmt(d.total_dues || 0);
	root_element.getElementById("sk-active-customers").textContent = d.active_customers ?? "--";
	root_element.getElementById("sk-total-customers").textContent = "of " + (d.total_customers ?? "--") + " total";
});

const btn = root_element.getElementById("sk-sync-btn");
const status = document.createElement("div");
status.id = "sk-sync-status";
status.style.cssText = "font-size:12px;color:#888;margin-top:6px;";
btn.parentElement.parentElement.appendChild(status);

frappe.realtime.on("kirana_console_sync_done", (r) => {
	btn.disabled = false;
	btn.textContent = "Sync Now";
	if (r.status === "success") {
		status.style.color = "#2a8";
		status.textContent = r.summary;
	} else {
		status.style.color = "#c33";
		status.textContent = "Sync failed: " + r.message;
	}
});

btn.onclick = () => {
	btn.disabled = true;
	btn.textContent = "Syncing...";
	status.style.color = "#888";
	status.textContent = "This can take a couple of minutes for a full catalog.";
	frappe.call({ method: "kirana_console.sync.sync_now" }).catch(() => {
		btn.disabled = false;
		btn.textContent = "Sync Now";
	});
};

(function () {
	let DATA = { active: [], not_onboarded: [], needs_review: [] };
	let TAB = "active";

	const fmt = n => "₹" + Math.round(n || 0).toLocaleString("en-IN");
	const tbody = root_element.getElementById("sk-cust-tbody");
	const thead = root_element.getElementById("sk-cust-thead");
	const empty = root_element.getElementById("sk-cust-empty");
	const search = root_element.getElementById("sk-cust-search");

	function showPin(mobile, pin) {
		root_element.getElementById("sk-pin-mobile").textContent = mobile;
		root_element.getElementById("sk-pin-value").textContent = pin;
		root_element.getElementById("sk-pin-modal").style.display = "flex";
	}
	root_element.getElementById("sk-pin-close").onclick = () => {
		root_element.getElementById("sk-pin-modal").style.display = "none";
		load();
	};

	function btn(label, color) {
		return `<button class="sk-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;margin-right:4px;">${label}</button>`;
	}

	function render() {
		const rows = DATA[TAB] || [];
		const q = (search.value || "").toLowerCase().trim();
		const filtered = q
			? rows.filter(r => (r.customer_name || "").toLowerCase().includes(q) || (r.mobile_no || "").includes(q))
			: rows;

		root_element.querySelectorAll(".sk-tab-btn").forEach(b => {
			const active = b.dataset.tab === TAB;
			b.style.background = active ? "#3E2417" : "#fff";
			b.style.color = active ? "#fff" : "#3E2417";
		});

		if (TAB === "active") {
			thead.innerHTML = "<th style='text-align:left;padding:8px;'>Shop</th><th style='text-align:left;padding:8px;'>Mobile</th><th style='text-align:left;padding:8px;'>Due</th><th style='text-align:left;padding:8px;'>Status</th><th style='padding:8px;'>Actions</th>";
			tbody.innerHTML = filtered.map(r => `
				<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${r.customer_name}</td>
					<td style="padding:8px;">${r.mobile_no || "-"}</td>
					<td style="padding:8px;">${fmt(r.due)}</td>
					<td style="padding:8px;">${r.status === "active" ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Revoked</span>"}</td>
					<td style="padding:8px;white-space:nowrap;">
						${btn("Reset PIN", "#3E2417")}
						${r.status === "active" ? btn("Revoke", "#c33") : btn("Restore", "#2a8")}
					</td>
				</tr>`).join("");
			tbody.querySelectorAll("tr").forEach((tr, i) => {
				const r = filtered[i];
				const [resetBtn, toggleBtn] = tr.querySelectorAll(".sk-act");
				resetBtn.onclick = () => frappe.call({ method: "stockist_reset_pin", args: { customer: r.customer } })
					.then(res => showPin(res.message.mobile_no, res.message.pin));
				toggleBtn.onclick = () => frappe.call({ method: "stockist_toggle_access", args: { customer: r.customer, enable: r.status === "active" ? 0 : 1 } })
					.then(() => load());
			});
		} else if (TAB === "not_onboarded") {
			thead.innerHTML = "<th style='text-align:left;padding:8px;'>Shop</th><th style='text-align:left;padding:8px;'>Mobile</th><th style='padding:8px;'>Actions</th>";
			tbody.innerHTML = filtered.map(r => `
				<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${r.customer_name}</td>
					<td style="padding:8px;">${r.mobile_no ? r.mobile_no : "<input type='tel' class='sk-mobile-input' placeholder='Enter mobile number' style='padding:4px;border:1px solid #ccc;border-radius:4px;width:130px;'>"}</td>
					<td style="padding:8px;">${btn("Grant Access", "#3E2417")}</td>
				</tr>`).join("");
			tbody.querySelectorAll("tr").forEach((tr, i) => {
				const r = filtered[i];
				const grantBtn = tr.querySelector(".sk-act");
				const input = tr.querySelector(".sk-mobile-input");
				grantBtn.onclick = () => {
					const mobile = r.mobile_no || (input && input.value.trim());
					if (!mobile) { frappe.msgprint("Enter a mobile number first."); return; }
					frappe.call({ method: "stockist_grant_access", args: { customer: r.customer, mobile_no: mobile } })
						.then(res => showPin(res.message.mobile_no, res.message.pin));
				};
			});
		} else {
			thead.innerHTML = "<th style='text-align:left;padding:8px;'>Shop</th><th style='text-align:left;padding:8px;'>Mobile</th><th style='text-align:left;padding:8px;'>Due</th>";
			tbody.innerHTML = filtered.map(r => `
				<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${r.customer_name}</td>
					<td style="padding:8px;">${r.mobile_no || "-"}</td>
					<td style="padding:8px;">${fmt(r.due)}</td>
				</tr>`).join("");
		}
		empty.style.display = filtered.length ? "none" : "block";
		root_element.getElementById("sk-cust-table-wrap").style.display = filtered.length ? "block" : "none";
	}

	function load() {
		frappe.call({ method: "stockist_customer_access_list" }).then(r => {
			DATA = r.message || DATA;
			render();
		});
	}

	root_element.querySelectorAll(".sk-tab-btn").forEach(b => {
		b.onclick = () => { TAB = b.dataset.tab; render(); };
	});
	search.oninput = render;

	load();
})();
